import React, { useEffect, useState, useRef } from "react";
import { Link, useNavigate } from "react-router-dom";

export const Navigation = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [dropdownVisible, setDropdownVisible] = useState(false);
  const [isClinic, setIsClinic] = useState(false);
  const dropdownRef = useRef(null);
  const navigate = useNavigate();
  const [avatar, setAvatar] = useState('');

  useEffect(() => {
    const token = localStorage.getItem("token");
    setIsLoggedIn(!!token);

    const ownerData = localStorage.getItem("owner");
    if (ownerData) {
      const owner = JSON.parse(ownerData);
      setAvatar(owner.avatar);
    }

    const clinicId = localStorage.getItem("clinicId");
    setIsClinic(!!clinicId); 

    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setDropdownVisible(false);
      }
    };

    window.addEventListener("click", handleClickOutside);
    return () => {
      window.removeEventListener("click", handleClickOutside);
    };
  }, []);

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("ownerId");
    localStorage.removeItem("role");
    localStorage.removeItem("clinicId");
    setIsLoggedIn(false);
    setAvatar('');
    navigate('/login');
  };

  const handleAvatarClick = () => {
    setDropdownVisible(true);
  };

  const handleProfileClick = () => {
    const ownerId = localStorage.getItem('ownerId');
    if (ownerId) {
      navigate(`/profile?id=${ownerId}`);
    }
  };

  return (
    <nav className="navbar navbar-default" style={{ position: 'fixed', width: '100%', zIndex: 1000, top: '0px' }}>
      <div className="container">
        <div className="navbar-header">
          <a className="navbar-brand page-scroll" href="/home">
            <img src={require('../assets/Logo.png')} alt="Petopia Logo" style={{ height: '60px' }} />
          </a>
        </div>
        <div className="collapse navbar-collapse">
          <ul className="nav navbar-nav navbar-right">
            {!isLoggedIn ? (
              <>
                <li><a href="/#header" className="page-scroll">Home</a></li>
                <li><Link to="/login">Log In</Link></li>
              </>
            ) : (
              <li style={{ position: 'relative' }} ref={dropdownRef}>
                <img
                  src={avatar || "default-avatar.png"}
                  alt="Profile"
                  style={{ width: '40px', height: '40px', borderRadius: '50%', cursor: 'pointer' }}
                  onClick={handleAvatarClick}
                />
                {dropdownVisible && (
                  <div style={{ position: 'absolute', backgroundColor: 'white', borderRadius: '4px', boxShadow: '0 2px 10px rgba(0, 0, 0, 0.2)', zIndex: 1001, marginTop: '10px' }}>
                    <div style={{ padding: '10px 20px', cursor: 'pointer' }} onClick={() => navigate('/home')}>
                      Home
                    </div>
                    {!isClinic && (
                      <div style={{ padding: '10px 20px', cursor: 'pointer' }} onClick={handleProfileClick}>
                        Profile
                      </div>
                    )}
                    <div style={{ padding: '10px 20px', cursor: 'pointer' }} onClick={handleLogout}>
                      Logout
                    </div>
                  </div>
                )}
              </li>
            )}
          </ul>
        </div>
      </div>
    </nav>
  );
};
